using UnityEngine;namespace SaveLoadSystemNamespace {	public class PlayerPrefsStrategy : ISaveLoadStrategy {		public void Save(ISaveLoadObject saveObject) {			var jsonData = saveObject.GetSaveLoadData();			PlayerPrefs.SetString(saveObject.objectKey, jsonData);		}		public void Load(ISaveLoadObject saveObject) {			var values = PlayerPrefs.GetString(saveObject.objectKey);			saveObject.RestoreValues(values);		}	}}